package main

import "fmt"

func main() {
    total := 0
    for n := 1; n <= 5; n++ {
        if n % 2 == 0 { continue }
        total += n
        if total >= 4 { break }
    }
    remaining := 2
    for remaining > 0 { remaining-- }
    fmt.Println(total, remaining)
}

fn main() {
    let mut total = 0;
    for n in 1..=5 {
        if n % 2 == 0 { continue; }
        total += n;
        if total >= 4 { break; }
    }
    let mut remaining = 2;
    while remaining > 0 { remaining -= 1; }
    println!("{} {}", total, remaining);
}

