#include <iostream>

int main() {
    int total = 0;
    for (int n = 1; n <= 5; ++n) {
        if (n % 2 == 0) { continue; }
        total += n;
        if (total >= 4) { break; }
    }
    int remaining = 2;
    while (remaining > 0) { --remaining; }
    std::cout << total << " " << remaining << "\n";
}

